return {rwnpc01={id="rwnpc01",dsc="她着一身白衣，长发披散，坐在路边低头哭泣，看着很是凄惨。你看不清她的面容，即使与她交谈，她也从未抬起过头。",sex="女",age=30,looks=19,showequip={},withCorpse=0},rwnpc02={id="rwnpc02",dsc="他发须花白，满面皱纹，已是风烛残年，正拄着拐杖坐在路边的大石头上。",sex="男",age=65,looks=15,showequip={},withCorpse=0},rwnpc03={id="rwnpc03",dsc="他发须花白，满面皱纹，却精气十足，赤着的上身十分健朗，两只手臂缠满布条，但行动时却不像是受伤了的样子。",sex="男",age=60,looks=17,showequip={},withCorpse=0},rwnpc04={id="rwnpc04",dsc="她是三河村的村民，或许因为常干农活看着神采奕奕，说话中气十足。她似乎受了伤，手腕处缠着布带。",sex="女",age=50,looks=18,showequip={},withCorpse=0},rwnpc05={id="rwnpc05",dsc="他是三河村的村民，看着你的眼神十分警惕。",sex="男",age=40,looks=19,showequip={},withCorpse=0},rwnpc06={id="rwnpc06",dsc="他是三河村的村长，看着容光焕发，不像是常做农事之人，气质儒雅更像是教书先生。他身上带着一股药味。",sex="男",age=45,looks=20,showequip={},withCorpse=0},rwnpc07={id="rwnpc07",dsc="他是三河村的村民，隐约能看见他衣领下的皮肤有些怪异。",sex="男",age=45,looks=18,showequip={},withCorpse=0},rwnpc08={id="rwnpc08",dsc="他是三河村的村民。",sex="男",age=45,looks=17,showequip={},withCorpse=0},rwnpc09={id="rwnpc09",dsc="他一身劲装，看着应该是个习武之人。",sex="男",age=45,looks=18,showequip={},withCorpse=0},rwnpc10={id="rwnpc10",dsc="三河村的村民深信她是灵蛇之母，是山神的在人间的化身。她总是神情漠然，向来深居简出，除村长外很少人能见到她。",sex="女",age=23,looks=20,showequip={},withCorpse=0},rwnpc11={id="rwnpc11",dsc="她便是你一直在找的孩子，她面色苍白得不似活人，瘦小的身体被群蛇咬得遍体鳞伤。",sex="女",age=23,looks=17,showequip={},withCorpse=0},rwnpc12={id="rwnpc12",dsc="他是被抓来的孩子，面色苍白，眼神呆滞，遍体鳞伤。",sex="男",age=11,looks=15,showequip={},withCorpse=0},rwnpc13={id="rwnpc13",dsc="官府弟子，凌云的兄长，和明宗宝、齐天关系十分要好。",sex="男",age=30,looks=20,showequip={},withCorpse=0},bsnpc01={id="bsnpc01",dsc="她全身湿漉漉地站在草丛里，脸色十分苍白。",sex="女",age=17,looks=19,showequip={},withCorpse=0},bsnpc02={id="bsnpc02",dsc="他蓬头垢面，衣衫破旧，直接靠在山神像上，毫无避讳。",sex="男",age=65,looks=15,showequip={},withCorpse=0},bsnpc03={id="bsnpc03",dsc="她锦衣华服，十分贵气，却常面露忧郁。",sex="女",age=35,looks=19,showequip={},withCorpse=0},bsnpc04={id="bsnpc04",dsc="他虽着锦衣，却是脸黄肌瘦，动不动便咳得不能自已。",sex="男",age=11,looks=20,showequip={},withCorpse=0},bsnpc05={id="bsnpc05",dsc="他是京城的商人，却时常往返这个偏僻的荒村。他面色红润，说话亦是中气十足，全然不像是曾患不治之症的病人。",sex="男",age=50,looks=19,showequip={},withCorpse=0},bsnpc06={id="bsnpc06",dsc="他是三河村的村民，总是阴沉着脸，他似乎很不高兴你进村。",sex="男",age=40,looks=20,showequip={},withCorpse=0},bsnpc07={id="bsnpc07",dsc="他是三河村的村民。",sex="男",age=40,looks=17,showequip={},withCorpse=0},bsnpc08={id="bsnpc08",dsc="她是三河村的村民，据说曾受过刺激，从此便不再说话了。",sex="女",age=13,looks=17,showequip={},withCorpse=0}}00000